    # Markers aligned on the same cell column/row define full cell tracks;
    # intersections of distinct tracks use the combined color.
    h, w = len(grid), len(grid[0])
    hr = [i for i, row in enumerate(grid) if all(v == 8 for v in row)]
    vc = [j for j in range(w) if all(grid[i][j] == 8 for i in range(h))]
    rstarts = [0] + [i + 1 for i in hr]
    rends = hr + [h]
    cstarts = [0] + [j + 1 for j in vc]
    cends = vc + [w]
    out = [row[:] for row in grid]
